type DeleteOptions struct {
    // ...
    Prompter prompt.Prompter
    Yes      bool
}

func NewCmdDelete(f *Factory, runF func(context.Context, *DeleteOptions) error) *cobra.Command {
    opts := &DeleteOptions{Prompter: f.Prompter}
    cmd := &cobra.Command{
        Use:   "delete <name>",
        Short: "Delete an item (prompts unless --yes)",
        RunE: func(c *cobra.Command, args []string) error {
            if runF != nil { return runF(c.Context(), opts) }
            return deleteRun(c.Context(), opts)
        },
    }
    cmd.Flags().BoolVarP(&opts.Yes, "yes", "y", false, "skip confirmation prompt")
    return cmd
}

func deleteRun(ctx context.Context, opts *DeleteOptions) error {
    if !opts.Yes {
        ok, err := opts.Prompter.Confirm(ctx, "Delete permanently?", false)
        if errors.Is(err, prompt.ErrNotTTY) {
            return fmt.Errorf("refusing to delete without --yes in non-interactive mode")
        }
        if err != nil { return err }
        if !ok { return ErrCancel }
    }
    // ...perform delete
}
```

```go
// internal/mytoolcmd/build/build.go
package build

import (
    "runtime/debug"
    "sync"
)

const (
    VersionDev  = "dev"
    CommitNone  = "none"
    DateUnknown = "unknown"
)

var (
    Version = VersionDev
    Commit  = CommitNone
    Date    = DateUnknown
)

type BuildInfo struct {
    Version, Commit, Date string
}

// Info returns the version/commit/date resolved from either ldflags
// (authoritative) or debug.ReadBuildInfo() (fallback for go install /
// go run). Safe for concurrent calls. sync.OnceValue (single-return —
// the closure never errors) so the BuildInfo scan runs at most once.
var Info = sync.OnceValue(func() BuildInfo {
    v, c, d := Version, Commit, Date
    if v == VersionDev {
        if info, ok := debug.ReadBuildInfo(); ok {
            for _, s := range info.Settings {
                switch s.Key {
                case "vcs.revision":
                    if c == CommitNone { c = s.Value }
                case "vcs.time":
                    if d == DateUnknown { d = s.Value }
                case "vcs.modified":
                    if s.Value == "true" { c += "-dirty" }
                }
            }
        }
    }
    return BuildInfo{Version: v, Commit: c, Date: d}
})
```

Callers read `info := build.Info()` and use `info.Version`,
`info.Commit`, `info.Date` directly — no destructure helper needed.

Makefile exports `LDFLAGS` once and both `build` and `release`
targets consume it; `.goreleaser.yml` uses `{{ .Env.LDFLAGS }}` or
its own template to produce the same `-X` entries. No init() in this
package — keep `go test -run -short` hermetic and avoid ordering
surprises.

