```go
// pkg/cmd/paths/atomic.go
func WriteFileAtomic(path string, data []byte, perm os.FileMode) error {
    dir := filepath.Dir(path)
    tmp, err := os.CreateTemp(dir, ".tmp-*")
    if err != nil { return err }
    tmpName := tmp.Name()
    defer os.Remove(tmpName) // no-op on success after rename

    if _, err := tmp.Write(data); err != nil {
        tmp.Close(); return err
    }
    if err := tmp.Sync(); err != nil {
        tmp.Close(); return err
    }
    if err := tmp.Close(); err != nil { return err }
    if err := os.Chmod(tmpName, perm); err != nil { return err }
    if err := os.Rename(tmpName, path); err != nil { return err }

    // fsync parent dir for durability. POSIX-only — on Windows a
    // directory-handle Sync() isn't the same durability barrier and
    // some filesystems return errors for it. Matches the scope in
    // the atomic-rename-samedir memory.
    if runtime.GOOS != "windows" {
        d, err := os.Open(dir)
        if err != nil { return err }
        defer d.Close()
        if err := d.Sync(); err != nil { return err }
    }
    return nil
}

// pkg/cmd/paths/lock_unix.go
//go:build unix

func WithLock(path string, fn func() error) error {
    f, err := os.OpenFile(path+".lock", os.O_CREATE|os.O_RDWR, 0o644)
    if err != nil { return err }
    defer f.Close()
    if err := unix.Flock(int(f.Fd()), unix.LOCK_EX); err != nil { return err }
    // Explicit unlock. f.Close() would also release the flock on
    // exit; keeping LOCK_UN makes the release point visible and
    // survives a refactor that defers close elsewhere.
    defer unix.Flock(int(f.Fd()), unix.LOCK_UN)
    return fn()
}

// pkg/cmd/paths/lock_windows.go
//go:build windows
//
// Use LockFileEx from golang.org/x/sys/windows with
// LOCKFILE_EXCLUSIVE_LOCK; unlock via UnlockFileEx. Same contract
// as WithLock above.
```

Pairs with the `atomic-rename-samedir` memory — one-line rule,
always-on.

```go
type State struct {
    SchemaVersion int    `json:"schema_version"`
    LastRepo      string `json:"last_repo,omitempty"`
    // ...
}

const CurrentSchemaVersion = 3

func Load(path string) (*State, error) {
    data, err := os.ReadFile(path)
    if err != nil { return nil, err }

    // Peek at the version first.
    var probe struct{ SchemaVersion int `json:"schema_version"` }
    if err := json.Unmarshal(data, &probe); err != nil {
        return nil, fmt.Errorf("parsing state version: %w", err)
    }
    if probe.SchemaVersion > CurrentSchemaVersion {
        return nil, fmt.Errorf(
            "state file version %d is newer than tool version %d; upgrade the tool",
            probe.SchemaVersion, CurrentSchemaVersion)
    }

    for v := probe.SchemaVersion; v < CurrentSchemaVersion; v++ {
        data, err = migrations[v](data)
        if err != nil { return nil, fmt.Errorf("migrating state v%d→v%d: %w", v, v+1, err) }
    }

    var s State
    if err := json.Unmarshal(data, &s); err != nil { return nil, err }
    // In-memory SchemaVersion reflects the migration target, not what's
    // on disk. The file still holds probe.SchemaVersion until the next
    // Save rewrites it with CurrentSchemaVersion.
    s.SchemaVersion = CurrentSchemaVersion
    return &s, nil
}

var migrations = map[int]func([]byte) ([]byte, error){
    1: migrateV1toV2,
    2: migrateV2toV3,
}
```

Writers always write `CurrentSchemaVersion`. Next save reconciles
the on-disk version with what's in memory.

